// ABOUTME: Cormorant Garamond fonts embedded as base64 for jsPDF.
// ABOUTME: Provides registerCormorantGaramond() to add regular and italic fonts to a jsPDF instance.

import type { jsPDF } from 'jspdf';

const CORMORANT_GARAMOND_REGULAR_BASE64 = '';

const CORMORANT_GARAMOND_ITALIC_BASE64 = '';

export function registerCormorantGaramond(doc: jsPDF): void {
	doc.addFileToVFS('CormorantGaramond-Regular.ttf', CORMORANT_GARAMOND_REGULAR_BASE64);
	doc.addFont('CormorantGaramond-Regular.ttf', 'CormorantGaramond', 'normal');
	
	doc.addFileToVFS('CormorantGaramond-Italic.ttf', CORMORANT_GARAMOND_ITALIC_BASE64);
	doc.addFont('CormorantGaramond-Italic.ttf', 'CormorantGaramond', 'italic');
}
